import os, time, vertexai
from vertexai.resources.preview import feature_store as vfs
project=os.environ['GCP_PROJECT']; loc=os.environ['GCP_LOCATION']; prefix=os.environ['MLPAB_GCP_PREFIX']
vertexai.init(project=project, location=loc, api_transport='rest')
store_id=f'{prefix}_store'
store=None
for attempt in range(6):
    try:
        store=vfs.FeatureOnlineStore.create_optimized_store(name=store_id)
        print('created store', store.resource_name); break
    except Exception as e:
        msg=str(e)[:150]
        print(f'attempt {attempt} failed: {msg}')
        # maybe it got created despite error
        try:
            store=vfs.FeatureOnlineStore(store_id); print('found existing', store.resource_name); break
        except Exception:
            pass
        time.sleep(30)
if store: print('DONE type', store.feature_online_store_type)
else: print('NO STORE')
